<script setup>
import { computed, reactive, ref } from 'vue'

const resultTabs=[['results','结果'],['compare','layer 对比'],['gradient','梯度 Spec'],['history','历史'],['fa','FA 关联']]
const activeTab=ref('setup')
const selectedTaskId=ref(null)
const tasks=ref([])
const tclInput=ref('density::analyze -layer M1 -step 100')
const tclLog=ref([])
const form=reactive({project:'',gdsName:'',layer:'M1',compareLayer:'M2',stepUm:100,widthUm:500,heightUm:500,gradientSpec:0.08})
const selectedTask=computed(()=>tasks.value.find(t=>t.id===selectedTaskId.value)||null)
function seed(text){let v=0;for(const c of String(text))v=(v*31+c.charCodeAt(0))>>>0;return v}
function densityValues(key,count=120,shift=0){return Array.from({length:count},(_,i)=>.38+((seed(`${key}-${i}`)%210)/1000)+shift)}
function makeResult(task){const values=densityValues(task.id);const mean=values.reduce((a,b)=>a+b,0)/values.length;const variance=values.reduce((a,b)=>a+(b-mean)**2,0)/values.length;const gradients=values.slice(1).map((v,i)=>Math.abs(v-values[i]));const gradient=Math.max(...gradients);const pValue=.06+(task.id%25)/100;return{values,mean,variance,gradients,gradient,pValue,pass:gradient<=task.gradientSpec&&pValue>=.05}}
function createTask(source='form'){const id=Date.now()+tasks.value.length;const task={id,name:`TASK-${String(tasks.value.length+1).padStart(3,'0')}`,project:form.project||'未命名项目',gdsName:form.gdsName||'demo.gds',layer:form.layer,compareLayer:form.compareLayer,stepUm:Number(form.stepUm),widthUm:Number(form.widthUm),heightUm:Number(form.heightUm),gradientSpec:Number(form.gradientSpec),source,createdAt:new Date().toLocaleString()};task.result=makeResult(task);tasks.value.unshift(task);selectedTaskId.value=task.id;activeTab.value='setup'}
function openTask(task){selectedTaskId.value=task.id;activeTab.value='results'}
function backToSetup(){activeTab.value='setup'}
function runTcl(){const command=tclInput.value.trim();if(!command)return;const layer=command.match(/-layer\s+(\S+)/i),step=command.match(/-step\s+(\d+(?:\.\d+)?)/i);if(layer)form.layer=layer[1];if(step)form.stepUm=Number(step[1]);const creates=/density::analyze|density::create/i.test(command);tclLog.value.unshift({command,time:new Date().toLocaleTimeString(),output:creates?'已新增一条 density 分析任务。':'command 已执行。'});if(creates)createTask('tcl')}
function setGradientSpec(value){if(!selectedTask.value)return;selectedTask.value.gradientSpec=Number(value);selectedTask.value.result.pass=selectedTask.value.result.gradient<=selectedTask.value.gradientSpec&&selectedTask.value.result.pValue>=.05}
const compareValues=computed(()=>selectedTask.value?densityValues(`${selectedTask.value.id}-${selectedTask.value.compareLayer}`,120,-.012):[])
const gradientBins=computed(()=>{if(!selectedTask.value)return[];const vals=selectedTask.value.result.gradients;const max=Math.max(...vals,selectedTask.value.gradientSpec,.001);return Array.from({length:12},(_,i)=>{const lo=i*max/12,hi=(i+1)*max/12;return{lo,hi,count:vals.filter(v=>v>=lo&&(i===11?v<=hi:v<hi)).length}})})
const historyData=computed(()=>selectedTask.value?[{project:selectedTask.value.project||'当前项目',mean:selectedTask.value.result.mean},{project:'History-A',mean:.468},{project:'History-B',mean:.451},{project:'History-C',mean:.492},{project:'History-D',mean:.438}]:[])
const faCases=computed(()=>{if(!selectedTask.value)return[];const p=selectedTask.value.project||'Demo';return[{caseId:'FA-2026-00127',project:p,product:'Falcon-A',technology:'N5',failType:'Open',failModel:'Via open / high resistance',layer:selectedTask.value.layer,status:'Confirmed'},{caseId:'FA-2026-00142',project:p,product:'Falcon-A',technology:'N5',failType:'Short',failModel:'Metal bridge',layer:selectedTask.value.compareLayer,status:'Suspect'},{caseId:'FA-2026-00168',project:p,product:'Falcon-B',technology:'N5',failType:'Leakage',failModel:'Local density hotspot correlation',layer:selectedTask.value.layer,status:'Confirmed'},{caseId:'FA-2026-00191',project:p,product:'Falcon-B',technology:'N4',failType:'Timing',failModel:'CMP dishing / RC shift',layer:selectedTask.value.layer,status:'Review'}]})
function heatColor(v){const t=Math.max(0,Math.min(1,(v-.38)/.21));const hue=220-t*190;return`hsl(${hue} 76% 52%)`}
</script>

<template>
<main class="density-task-page">
<header class="page-head"><div><div class="eyebrow">GDS · density · layer</div><h1>GDS Density 分析</h1><p>在 Set Up 创建任务，再从“已创建任务”进入该任务结果。</p></div><button v-if="activeTab!=='setup'" class="secondary" @click="backToSetup">← 返回 Set Up</button></header>
<nav v-if="activeTab==='setup'" class="top-nav"><button class="active">Set Up</button></nav>
<div v-else-if="selectedTask" class="task-subnav"><div class="crumb"><button @click="backToSetup">Set Up</button><span>›</span><strong>{{ selectedTask.name }}</strong></div><nav><button v-for="tab in resultTabs" :key="tab[0]" :class="{active:activeTab===tab[0]}" @click="activeTab=tab[0]">{{ tab[1] }}</button></nav></div>
<section v-if="activeTab==='setup'" class="workspace setup-layout">
<div class="panel"><div class="panel-head"><div><span>SET UP</span><h2>创建 density 分析任务</h2></div><button class="primary" @click="createTask('form')">创建任务</button></div><div class="form-grid"><label><span>项目</span><input v-model="form.project" placeholder="项目名称"></label><label><span>GDS 文件</span><input v-model="form.gdsName" placeholder="example.gds"></label><label><span>GDS layer</span><input v-model="form.layer"></label><label><span>对比 layer</span><input v-model="form.compareLayer"></label><label><span>窗口 step</span><input v-model.number="form.stepUm" type="number"></label><label><span>窗口宽度</span><input v-model.number="form.widthUm" type="number"></label><label><span>窗口高度</span><input v-model.number="form.heightUm" type="number"></label><label><span>Gradient Spec</span><input v-model.number="form.gradientSpec" type="number" step="0.005"></label></div></div>
<div class="panel"><div class="panel-head"><div><span>TCL COMMAND</span><h2>在 Set Up 中调用 TCL command</h2></div></div><div class="terminal"><div class="terminal-log"><div v-if="!tclLog.length" class="terminal-empty">示例：density::analyze -layer M1 -step 100</div><div v-for="(l,i) in tclLog" :key="i"><p><small>{{ l.time }}</small> $ {{ l.command }}</p><pre>{{ l.output }}</pre></div></div><form @submit.prevent="runTcl"><span>$</span><input v-model="tclInput"><button>运行</button></form></div></div>
<div class="panel full"><div class="panel-head"><div><span>TASKS</span><h2>已创建任务</h2></div><small>结果只能从这里进入</small></div><div v-if="!tasks.length" class="empty">暂无任务</div><table v-else><thead><tr><th>任务</th><th>项目</th><th>GDS</th><th>layer</th><th>step</th><th>来源</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="task in tasks" :key="task.id"><td><strong>{{ task.name }}</strong></td><td>{{ task.project }}</td><td>{{ task.gdsName }}</td><td>{{ task.layer }}</td><td>{{ task.stepUm }} µm</td><td>{{ task.source==='tcl'?'TCL':'表单' }}</td><td><span :class="task.result.pass?'ok-pill':'warn-pill'">{{ task.result.pass?'通过':'需检查' }}</span></td><td><button class="link" @click="openTask(task)">查看结果</button></td></tr></tbody></table></div>
</section>
<section v-else-if="selectedTask" class="workspace result-grid">
<div class="panel full task-summary"><div><span>任务</span><strong>{{ selectedTask.name }}</strong></div><div><span>项目</span><strong>{{ selectedTask.project }}</strong></div><div><span>GDS</span><strong>{{ selectedTask.gdsName }}</strong></div><div><span>layer</span><strong>{{ selectedTask.layer }}</strong></div><div><span>窗口</span><strong>{{ selectedTask.widthUm }} × {{ selectedTask.heightUm }} µm</strong></div></div>
<template v-if="activeTab==='results'"><div class="metric"><span>平均 density</span><strong>{{ (selectedTask.result.mean*100).toFixed(2) }}%</strong></div><div class="metric"><span>方差</span><strong>{{ selectedTask.result.variance.toFixed(5) }}</strong></div><div class="metric"><span>均匀性 p-value</span><strong>{{ selectedTask.result.pValue.toFixed(3) }}</strong></div><div class="metric"><span>最大梯度</span><strong>{{ (selectedTask.result.gradient*100).toFixed(2) }}%</strong></div><div class="metric"><span>综合结果</span><strong :class="selectedTask.result.pass?'ok-text':'warn-text'">{{ selectedTask.result.pass?'通过':'需检查' }}</strong></div><div class="panel full"><div class="panel-head"><div><span>HEATMAP</span><h2>{{ selectedTask.layer }} density heatmap</h2></div></div><div class="heatmap"><i v-for="(v,i) in selectedTask.result.values" :key="i" :style="{background:heatColor(v)}" :title="`${(v*100).toFixed(2)}%`"></i></div><div class="colorbar"><span>38%</span><div></div><span>59%</span></div></div></template>
<template v-else-if="activeTab==='compare'"><div class="panel full"><div class="panel-head"><div><span>LAYER COMPARE</span><h2>不同 layer 同区域 heatmap 对比</h2></div></div><div class="dual-heat"><div><h3>{{ selectedTask.layer }}</h3><div class="heatmap"><i v-for="(v,i) in selectedTask.result.values" :key="i" :style="{background:heatColor(v)}"></i></div><div class="colorbar"><span>38%</span><div></div><span>59%</span></div></div><div><h3>{{ selectedTask.compareLayer }}</h3><div class="heatmap"><i v-for="(v,i) in compareValues" :key="i" :style="{background:heatColor(v)}"></i></div><div class="colorbar"><span>38%</span><div></div><span>59%</span></div></div></div><div class="compare-cards"><div><span>{{ selectedTask.layer }} mean</span><strong>{{ (selectedTask.result.mean*100).toFixed(2) }}%</strong></div><div><span>{{ selectedTask.compareLayer }} mean</span><strong>{{ ((compareValues.reduce((a,b)=>a+b,0)/compareValues.length)*100).toFixed(2) }}%</strong></div><div><span>区域相关性</span><strong>0.936</strong></div></div></div></template>
<template v-else-if="activeTab==='gradient'"><div class="panel full"><div class="panel-head"><div><span>GRADIENT SPEC</span><h2>Gradient 分布与 Spec</h2></div><label class="spec-input"><span>Gradient Spec</span><input :value="selectedTask.gradientSpec" type="number" step="0.005" min="0.001" @input="setGradientSpec($event.target.value)"></label></div><div class="hist-chart"><div v-for="(b,i) in gradientBins" :key="i" class="hist-col"><div class="bar" :style="{height:`${Math.max(4,b.count/Math.max(...gradientBins.map(x=>x.count))*180)}px`}"><small>{{ b.count }}</small></div><span>{{ b.lo.toFixed(2) }}</span></div><div class="spec-line" :style="{left:`${Math.min(98,selectedTask.gradientSpec/Math.max(...selectedTask.result.gradients,selectedTask.gradientSpec)*100)}%`}"><b>Spec {{ selectedTask.gradientSpec.toFixed(3) }}</b></div></div><div class="spec-cards"><div><span>实测最大梯度</span><strong>{{ selectedTask.result.gradient.toFixed(4) }}</strong></div><div><span>Spec</span><strong>{{ selectedTask.gradientSpec.toFixed(4) }}</strong></div><div><span>判定</span><strong :class="selectedTask.result.gradient<=selectedTask.gradientSpec?'ok-text':'warn-text'">{{ selectedTask.result.gradient<=selectedTask.gradientSpec?'符合 Spec':'超出 Spec' }}</strong></div></div></div></template>
<template v-else-if="activeTab==='history'"><div class="panel full"><div class="panel-head"><div><span>HISTORY</span><h2>不同项目平均 density 对比</h2></div></div><div class="bar-chart"><div v-for="row in historyData" :key="row.project" class="project-bar"><strong>{{ (row.mean*100).toFixed(1) }}%</strong><div :style="{height:`${row.mean*360}px`}"></div><span>{{ row.project }}</span></div></div><table><thead><tr><th>项目</th><th>layer</th><th>平均 density</th><th>备注</th></tr></thead><tbody><tr v-for="(row,i) in historyData" :key="row.project"><td>{{ row.project }}</td><td>{{ selectedTask.layer }}</td><td>{{ (row.mean*100).toFixed(2) }}%</td><td>{{ i===0?'当前任务':'历史项目' }}</td></tr></tbody></table></div></template>
<template v-else-if="activeTab==='fa'"><div class="panel full"><div class="panel-head"><div><span>FA LIBRARY</span><h2>构造的 FA Library case</h2></div><small>按当前项目 / GDS / layer 关联展示</small></div><table><thead><tr><th>Case ID</th><th>项目</th><th>产品</th><th>工艺</th><th>fail type</th><th>fail model</th><th>layer</th><th>状态</th></tr></thead><tbody><tr v-for="row in faCases" :key="row.caseId"><td><strong>{{ row.caseId }}</strong></td><td>{{ row.project }}</td><td>{{ row.product }}</td><td>{{ row.technology }}</td><td>{{ row.failType }}</td><td>{{ row.failModel }}</td><td>{{ row.layer }}</td><td><span :class="row.status==='Confirmed'?'ok-pill':'warn-pill'">{{ row.status }}</span></td></tr></tbody></table></div></template>
</section>
</main>
</template>

<style scoped>
.density-task-page{margin-left:272px;padding:78px 28px 48px;min-height:100vh;background:#f5f7fa;color:#1f2937}.page-head{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;margin-bottom:16px}.page-head h1{margin:4px 0 6px;font-size:28px}.page-head p{margin:0;color:#667085;font-size:13px}.eyebrow,.panel-head>div>span{font-size:10px;font-weight:800;letter-spacing:.12em;color:#7b8490}.top-nav,.task-subnav nav{display:flex;gap:4px;border-bottom:1px solid #d9dee5;margin-bottom:18px}.top-nav button,.task-subnav nav button{border:0;background:transparent;padding:10px 14px;font-weight:700;color:#667085;border-bottom:2px solid transparent}.top-nav button.active,.task-subnav nav button.active{color:#17212b;border-bottom-color:#17212b}.task-subnav{margin-bottom:18px}.crumb{display:flex;align-items:center;gap:8px;font-size:12px;margin-bottom:5px;color:#667085}.crumb button{border:0;background:none;color:#2563eb;font-weight:700;padding:0}.workspace{display:grid;gap:16px}.setup-layout{grid-template-columns:1.15fr .85fr}.result-grid{grid-template-columns:repeat(5,minmax(0,1fr))}.full{grid-column:1/-1}.panel,.metric{background:#fff;border:1px solid #dfe4ea;border-radius:10px;padding:18px}.panel-head{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;margin-bottom:16px}.panel-head h2{margin:3px 0 0;font-size:16px}.primary,.secondary{height:36px;padding:0 15px;border-radius:7px;font-weight:700}.primary{border:0;background:#2563eb;color:#fff}.secondary{border:1px solid #cfd6df;background:#fff}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.form-grid label,.spec-input{display:grid;gap:5px}.form-grid label span,.spec-input span{font-size:11px;font-weight:700;color:#667085}.form-grid input,.spec-input input{height:38px;border:1px solid #cfd6df;border-radius:7px;padding:0 10px}.terminal{height:285px;background:#101720;color:#d7e0ea;border-radius:8px;display:flex;flex-direction:column;overflow:hidden}.terminal-log{flex:1;overflow:auto;padding:12px}.terminal-log p{margin:0 0 4px;font-size:12px}.terminal-log pre{margin:0 0 12px;color:#9fd8b7}.terminal-empty{color:#8190a3}.terminal form{display:flex;gap:8px;border-top:1px solid #263446;padding:8px}.terminal input{flex:1;background:transparent;border:0;outline:0;color:#fff}.terminal button{background:#1e293b;color:#fff;border:1px solid #475569;border-radius:5px;padding:0 12px}.panel table{width:100%;border-collapse:collapse;font-size:12px}.panel th,.panel td{padding:11px 10px;border-bottom:1px solid #edf0f4;text-align:left}.link{border:0;background:none;color:#2563eb;font-weight:700}.ok-pill,.warn-pill{display:inline-flex;padding:3px 8px;border-radius:999px}.ok-pill{background:#e7f7ef;color:#087553}.warn-pill{background:#fff1e8;color:#b54708}.empty{padding:30px;text-align:center;color:#7b8490}.task-summary{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px}.task-summary span,.metric span,.compare-cards span,.spec-cards span{display:block;font-size:10px;color:#7b8490;margin-bottom:5px}.task-summary strong{font-size:12px}.metric strong{font-size:20px}.ok-text{color:#087553}.warn-text{color:#b54708}.heatmap{display:grid;grid-template-columns:repeat(15,1fr);gap:3px}.heatmap i{aspect-ratio:1;border-radius:2px}.colorbar{display:flex;align-items:center;gap:8px;margin-top:10px;font-size:10px;color:#667085}.colorbar div{height:9px;flex:1;border-radius:99px;background:linear-gradient(90deg,hsl(220 76% 52%),hsl(125 76% 52%),hsl(30 76% 52%))}.dual-heat{display:grid;grid-template-columns:1fr 1fr;gap:20px}.dual-heat h3{margin:0 0 10px;font-size:14px}.compare-cards,.spec-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:18px}.compare-cards div,.spec-cards div{background:#f8fafc;border:1px solid #e7ebf0;border-radius:8px;padding:12px}.hist-chart{height:240px;display:flex;align-items:flex-end;gap:5px;position:relative;border-bottom:1px solid #d9dee5;padding:0 6px 28px}.hist-col{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%;position:relative}.hist-col .bar{width:100%;background:#334155;border-radius:4px 4px 0 0;position:relative}.hist-col .bar small{position:absolute;top:-16px;width:100%;text-align:center;font-size:9px}.hist-col>span{position:absolute;bottom:-22px;font-size:9px;color:#7b8490}.spec-line{position:absolute;top:0;bottom:28px;width:2px;background:#dc2626}.spec-line b{position:absolute;top:4px;left:5px;white-space:nowrap;font-size:10px;color:#b91c1c}.bar-chart{height:260px;display:flex;align-items:flex-end;gap:18px;padding:20px 18px 34px;border-bottom:1px solid #e5e7eb}.project-bar{flex:1;height:100%;display:flex;flex-direction:column;justify-content:flex-end;align-items:center;position:relative}.project-bar div{width:58%;min-height:8px;background:#334155;border-radius:5px 5px 0 0}.project-bar strong{font-size:11px;margin-bottom:5px}.project-bar span{position:absolute;bottom:-24px;font-size:10px;color:#667085}.sidebar-collapsed .density-task-page{margin-left:68px}@media(max-width:900px){.density-task-page{margin-left:68px;padding:72px 14px 30px}.setup-layout,.dual-heat{grid-template-columns:1fr}.result-grid{grid-template-columns:repeat(2,1fr)}.task-summary{grid-template-columns:repeat(2,1fr)}}
</style>
